//! 🛂️ Original encoder allocation quote and settlement retain both actual authority transactions.
use crate::{NativeAllocationRequest,NativeEncodeAllocationOutcome,ValueError,ValueRefusalKind};
use semio_framework_value_control_contract::NativeSendAllocationLoan;
fn commit_admission(ledger:&mut semio_framework_value_receiving::NativeAllocationLedger,request:NativeAllocationRequest)->Result<(),ValueError>{ledger.commit(request)}
/// 🪢️ Holds the actual forwarded allocation loan or local admission.
pub enum NativeEncodeAllocationBinding<'a>{Local,Forwarded(&'a mut (dyn NativeSendAllocationLoan+'a))}
/// 🚦️ Records whether an original port callback may already have taken effect.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum NativeEncodeAllocationPhase{Absent,QuoteStarted,QuoteAccepted,QuoteRefused,SettlementStarted,Settled}
/// 🧭️ Retains the original allocation request and callback boundaries during unwinding.
pub struct NativeEncodeAllocationProgress{request:NativeAllocationRequest,outcome:NativeEncodeAllocationOutcome,forwarded:NativeEncodeAllocationPhase,scoped:NativeEncodeAllocationPhase,operation_started:bool,prepared_for_producer:bool,settled:bool,settlement_actual:Option<Option<usize>>,forwarded_identity:Option<semio_framework_value_control_contract::NativeAllocationIdentity>,scoped_identity:Option<semio_framework_value_control_contract::NativeAllocationIdentity>,forwarded_transaction:Option<semio_framework_value_control_contract::NativeAllocationTransaction>,scoped_transaction:Option<semio_framework_value_control_contract::NativeAllocationTransaction>,forwarded_verdict:Option<Result<(),crate::NativeAllocationRefusal>>,scoped_verdict:Option<Result<(),crate::NativeAllocationRefusal>>}
impl NativeEncodeAllocationProgress{
 /// 🌱️ Constructs one checked original request bound to its actual port identities.
 pub fn new(request:NativeAllocationRequest,forwarded_identity:Option<semio_framework_value_control_contract::NativeAllocationIdentity>,scoped_identity:Option<semio_framework_value_control_contract::NativeAllocationIdentity>,prepared_for_producer:bool)->Result<Self,ValueError>{if request.owned_bytes.checked_add(request.bytes)!=Some(request.next_owned_bytes)||request.next_owned_bytes>request.maximum_bytes{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"invalid original allocation request"))}Ok(Self{request,outcome:NativeEncodeAllocationOutcome{request:Some(request),admitted:false,primary:None,forwarded_quote:None,scoped_quote:None,extent_refusal:None,forwarded_refusal:None,scoped_refusal:None,actual:None},forwarded:if forwarded_identity.is_some(){NativeEncodeAllocationPhase::QuoteStarted}else{NativeEncodeAllocationPhase::Absent},scoped:if scoped_identity.is_some(){NativeEncodeAllocationPhase::QuoteStarted}else{NativeEncodeAllocationPhase::Absent},operation_started:false,prepared_for_producer,settled:false,settlement_actual:None,forwarded_identity,scoped_identity,forwarded_transaction:None,scoped_transaction:None,forwarded_verdict:None,scoped_verdict:None})}
 /// 🚦️ Reports any original quote refusal.
 pub fn quote_refused(&self)->bool{self.outcome.forwarded_quote.is_some()||self.outcome.scoped_quote.is_some()}
 /// ▶️ Starts the original producer only after both quote verdicts are accepted.
 pub fn start_operation(&mut self)->Result<(),ValueError>{if self.operation_started||self.settled||self.quote_refused()||!matches!(self.forwarded,NativeEncodeAllocationPhase::Absent|NativeEncodeAllocationPhase::QuoteAccepted)||!matches!(self.scoped,NativeEncodeAllocationPhase::Absent|NativeEncodeAllocationPhase::QuoteAccepted){return Err(ValueError::invariant("original allocation quote is not accepted"))}self.operation_started=true;Ok(())}
 /// 📏️ Records the actual producer marker without replacing an earlier physical result.
 pub fn record_actual(&mut self,actual:Option<usize>)->Result<(),ValueError>{if !self.operation_started||self.outcome.actual.is_some()&&self.outcome.actual!=actual{return Err(ValueError::invariant("original allocation marker changed"))}self.outcome.actual=actual;Ok(())}
 /// 🧳️ Retains the original producer error without overwriting another owner.
 pub fn record_primary(&mut self,error:ValueError)->Result<(),ValueError>{if self.outcome.primary.is_some(){return Err(error)}self.outcome.primary=Some(error);Ok(())}
 /// 🪪️ Borrows the exact original request without exposing mutable authority.
 pub fn request(&self)->NativeAllocationRequest{self.request}
 /// 📊️ Borrows the retained outcome without modifying callback history.
 pub fn outcome(&self)->&NativeEncodeAllocationOutcome{&self.outcome}
 /// 🔍️ Reports whether the producer began its effect.
 pub fn operation_started(&self)->bool{self.operation_started}
 /// 🎟️ Observes whether this quote was issued for the resident producer.
 pub fn prepared_for_producer(&self)->bool{self.prepared_for_producer}
 /// 🚦️ Observes the original callback boundary.
 pub fn forwarded_phase(&self)->NativeEncodeAllocationPhase{self.forwarded}pub fn scoped_phase(&self)->NativeEncodeAllocationPhase{self.scoped}
 /// 🪪️ Checks that this pending scoped action still belongs to its original allocation authority.
 pub fn matches_scoped_authority(&self,loan:&dyn NativeSendAllocationLoan)->bool{self.forwarded_identity.is_none()&&self.forwarded_transaction.is_none()&&self.scoped_identity==Some(loan.identity())&&loan.matches_transaction(self.scoped_transaction.as_ref())}
 /// 🫴️ Transfers the outcome only after every original callback is settled.
 pub fn into_outcome(self)->Result<NativeEncodeAllocationOutcome,Self>{if self.pending(){Err(self)}else{let owner=std::mem::ManuallyDrop::new(self);Ok(unsafe{std::ptr::read(&owner.outcome)})}}
 /// ⏳️ Reports whether original callback custody remains unresolved.
 pub fn is_pending(&self)->bool{self.pending()}
}
impl NativeEncodeAllocationProgress{
 /// 🧭️ Reports whether an original callback still requires resolution.
 pub fn pending(&self)->bool{(self.operation_started&&!self.settled)||matches!(self.forwarded,NativeEncodeAllocationPhase::QuoteStarted|NativeEncodeAllocationPhase::QuoteAccepted|NativeEncodeAllocationPhase::SettlementStarted)||matches!(self.scoped,NativeEncodeAllocationPhase::QuoteStarted|NativeEncodeAllocationPhase::QuoteAccepted|NativeEncodeAllocationPhase::SettlementStarted)||self.forwarded_transaction.is_some()||self.scoped_transaction.is_some()||self.forwarded_verdict.is_some()||self.scoped_verdict.is_some()}}
impl Drop for NativeEncodeAllocationProgress{fn drop(&mut self){assert!(std::thread::panicking()||!self.pending(),"original allocation callback remains unsettled")}}
impl crate::retirement::RetireOwned for NativeEncodeAllocationProgress{
 type RetirementCursor=semio_framework_value_receiving::NativeRetirementGate<Self,<NativeEncodeAllocationOutcome as crate::retirement::RetireOwned>::RetirementCursor>;
 fn retirement_ready(&self)->bool{!self.pending()&&crate::retirement::RetireOwned::retirement_ready(&self.outcome)}
 fn retirement_seed(self)->Self::RetirementCursor{if !crate::retirement::RetireOwned::retirement_ready(&self){return semio_framework_value_receiving::NativeRetirementGate::Pending(self)}match self.into_outcome(){Ok(outcome)=>semio_framework_value_receiving::NativeRetirementGate::Ready(crate::retirement::RetireOwned::retirement_seed(outcome)),Err(original)=>semio_framework_value_receiving::NativeRetirementGate::Pending(original)}}
 fn retirement_birth_bytes(&self)->Option<usize>{crate::retirement::RetireOwned::retirement_ready(self).then_some(std::mem::size_of::<Self::RetirementCursor>())}
 fn controlled_retirement_supported()->bool{true}
}

fn drive_encode_quote(port:&mut dyn NativeSendAllocationLoan,request:NativeAllocationRequest,phase:&mut NativeEncodeAllocationPhase,transaction:&mut Option<semio_framework_value_control_contract::NativeAllocationTransaction>,verdict:&mut Option<Result<(),crate::NativeAllocationRefusal>>,refusal:&mut Option<crate::NativeAllocationRefusal>)->Result<bool,ValueError>{use semio_framework_value_control_contract::NativeAllocationTransactionPhase as Phase;if transaction.is_none(){port.begin(request,true,transaction)?}else{let state=transaction.as_mut().expect("original quote transaction");if state.request()!=request{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation quote request changed"))}if state.phase()==Phase::QuoteStarted&&!port.recover(state)?{return Ok(false)}}let state=transaction.as_mut().expect("original quote transaction");if state.phase()==Phase::QuoteStarted{return Ok(false)}if verdict.is_none(){*verdict=state.take_verdict()}let Some(reply)=verdict.as_ref()else{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation quote verdict is absent"))};if reply.is_err(){port.finish(transaction)?}match verdict.take().expect("original quote verdict retained"){Ok(())=>*phase=NativeEncodeAllocationPhase::QuoteAccepted,Err(error)=>{*phase=NativeEncodeAllocationPhase::QuoteRefused;*refusal=Some(error)}}Ok(true)}
fn drive_encode_settlement(port:&mut dyn NativeSendAllocationLoan,request:NativeAllocationRequest,actual:Option<usize>,phase:&mut NativeEncodeAllocationPhase,transaction:&mut Option<semio_framework_value_control_contract::NativeAllocationTransaction>,verdict:&mut Option<Result<(),crate::NativeAllocationRefusal>>,refusal:&mut Option<crate::NativeAllocationRefusal>)->Result<bool,ValueError>{use semio_framework_value_control_contract::NativeAllocationTransactionPhase as Phase;let state=transaction.as_mut().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation quote is absent"))?;if state.request()!=request{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation settlement request changed"))}match state.phase(){Phase::QuoteAccepted=>port.settle(state,actual)?,Phase::PostStarted|Phase::CancelStarted=>if !port.recover(state)?{return Ok(false)},Phase::Settled=>{},_=>return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation settlement phase changed"))}let state=transaction.as_mut().expect("original settlement transaction");if matches!(state.phase(),Phase::PostStarted|Phase::CancelStarted){return Ok(false)}if verdict.is_none(){*verdict=state.take_verdict()}if verdict.is_none(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original settlement verdict is absent"))}port.finish(transaction)?;*refusal=verdict.take().expect("original settlement verdict retained").err();*phase=NativeEncodeAllocationPhase::Settled;Ok(true)}
/// 🛂️ Advances both exact original quote transactions.
pub fn advance_encode_quotes(allocation:&mut NativeEncodeAllocationBinding<'_>,scoped:&mut Option<&mut (dyn NativeSendAllocationLoan+'_)>,state:&mut NativeEncodeAllocationProgress)->Result<bool,ValueError>{let forwarded=match &mut *allocation{NativeEncodeAllocationBinding::Forwarded(port)=>Some(port.identity()),NativeEncodeAllocationBinding::Local=>None};let scoped_identity=scoped.as_ref().map(|port|port.identity());if forwarded!=state.forwarded_identity||scoped_identity!=state.scoped_identity{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation authority changed"))}if state.forwarded==NativeEncodeAllocationPhase::QuoteStarted{let NativeEncodeAllocationBinding::Forwarded(port)=&mut *allocation else{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"forwarded allocation owner is absent"))};if !drive_encode_quote(&mut **port,state.request,&mut state.forwarded,&mut state.forwarded_transaction,&mut state.forwarded_verdict,&mut state.outcome.forwarded_quote)?{return Ok(false)}}if state.scoped==NativeEncodeAllocationPhase::QuoteStarted{let port=scoped.as_mut().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"scoped allocation owner is absent"))?;if !drive_encode_quote(&mut **port,state.request,&mut state.scoped,&mut state.scoped_transaction,&mut state.scoped_verdict,&mut state.outcome.scoped_quote)?{return Ok(false)}}Ok(true)}
/// 🧾️ Settles the same original quote with its actual physical marker.
pub fn settle_encode_allocation(allocation:&mut NativeEncodeAllocationBinding<'_>,scoped:&mut Option<&mut (dyn NativeSendAllocationLoan+'_)>,ledger:&mut semio_framework_value_receiving::NativeAllocationLedger,state:&mut NativeEncodeAllocationProgress,actual:Option<usize>)->Result<bool,ValueError>{let forwarded=match &mut *allocation{NativeEncodeAllocationBinding::Forwarded(port)=>Some(port.identity()),NativeEncodeAllocationBinding::Local=>None};let scoped_identity=scoped.as_ref().map(|port|port.identity());if forwarded!=state.forwarded_identity||scoped_identity!=state.scoped_identity||matches!(state.forwarded,NativeEncodeAllocationPhase::QuoteStarted)||matches!(state.scoped,NativeEncodeAllocationPhase::QuoteStarted)||state.settled{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"allocation progress requires its original settled quotes"))}if actual.is_some()&&!state.operation_started{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"allocation cannot report an unperformed effect"))}if state.settlement_actual.is_some_and(|original|original!=actual)||state.outcome.actual.is_some()&&state.outcome.actual!=actual{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"allocation actual differs from retained progress"))}state.settlement_actual=Some(actual);state.outcome.actual=actual;if let Some(bytes)=actual{if !state.outcome.admitted{if ledger.owned_bytes()!=state.request.owned_bytes{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation ledger changed"))}commit_admission(ledger,state.request)?;state.outcome.admitted=true}else if ledger.owned_bytes()!=state.request.next_owned_bytes{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation ledger changed"))}if bytes>state.request.bytes&&state.outcome.extent_refusal.is_none(){state.outcome.extent_refusal=Some(ValueError::literal(ValueRefusalKind::InvariantViolated,"actual native allocation exceeds its quote"))}}if matches!(state.forwarded,NativeEncodeAllocationPhase::QuoteAccepted|NativeEncodeAllocationPhase::SettlementStarted){let NativeEncodeAllocationBinding::Forwarded(port)=&mut *allocation else{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"forwarded allocation owner is absent"))};state.forwarded=NativeEncodeAllocationPhase::SettlementStarted;if !drive_encode_settlement(&mut **port,state.request,actual,&mut state.forwarded,&mut state.forwarded_transaction,&mut state.forwarded_verdict,&mut state.outcome.forwarded_refusal)?{return Ok(false)}}if matches!(state.scoped,NativeEncodeAllocationPhase::QuoteAccepted|NativeEncodeAllocationPhase::SettlementStarted){let port=scoped.as_mut().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"scoped allocation owner is absent"))?;state.scoped=NativeEncodeAllocationPhase::SettlementStarted;if !drive_encode_settlement(&mut **port,state.request,actual,&mut state.scoped,&mut state.scoped_transaction,&mut state.scoped_verdict,&mut state.outcome.scoped_refusal)?{return Ok(false)}}state.settled=true;Ok(true)}

